content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-009

=== 用户原始指令 (query.txt) ===
整个免打扰卡片,点一下就能打电话,显示今天天气

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个免打扰卡片,点一下就能打电话,显示今天天气",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToCallPhone",
      "args": {
        "phoneNumber": "10086"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称。",
            "sampleValue": "青浦区"
          },
          "prefectureName": {
            "type": "string",
            "description": "天气查询的城市名称。",
            "sampleValue": "上海市"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前摄氏温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级。",
            "sampleValue": "良"
          },
          "humidityPercent": {
            "type": "number",
            "description": "当前相对湿度百分比。",
            "sampleValue": 62
          }
        },
        "daily": {
          "0": {
            "weekday": {
              "type": "string",
              "description": "今天的星期文本。",
              "sampleValue": "今天"
            },
            "temperatureRangeText": {
              "type": "string",
              "description": "今天的温度范围展示文本。",
              "sampleValue": "23° / 29°"
            },
            "rainProbabilityPercent": {
              "type": "string",
              "description": "今天白天降雨概率百分比。",
              "sampleValue": "20%"
            }
          }
        }
      }
    },
    "contact": {
      "phoneNumber": {
        "type": "string",
        "description": "点击整张卡片后拨打的电话号码。",
        "sampleValue": "10086"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注模式图标，适合表达免打扰或专注状态。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合表达多云天气。"
    }
  ]
}

